// Historical saves share accepted geometry, while every test owns its state and storage.
let accepted:Scene|undefined,acceptedSnapshot:string|undefined;
function currentScene(){
 if(!accepted){accepted=createWorldScene();acceptedSnapshot=JSON.stringify(accepted);}
 return accepted;
}
afterAll(()=>{if(accepted)expect(JSON.stringify(accepted)).toBe(acceptedSnapshot);});

function expectPopulation(state:CarState,previous:any,scene:Scene,prior=preVergeScene(scene)){
 const normalize=(population:any,world:Scene)=>{const nodes=ambientNavigation(world).nodes;return {...population,members:population.members.map((m:any)=>({...m,node:m.node<0 ? m.node : nodes[m.node],previous:m.previous<0 ? m.previous : nodes[m.previous]})).map(({node,previous,...m}:any)=>({...m,node:node && typeof node==='object' ? {x:node.x,y:node.y} : node,previous:previous && typeof previous==='object' ? {x:previous.x,y:previous.y} : previous}))};};
 expect(normalize(state.population,scene)).toEqual(normalize(previous,prior));
}
function priorProgressEconomy(e:any){e=preBusinessEconomy(e);const {unattributed,...old}=e;return {...old,accounts:e.accounts.map(({completed,...a}:any)=>a),batches:Object.fromEntries(Object.entries(e.batches).filter(([id])=>id!=='large_bake'))};}
function priorRecipeEconomy(e:any){
 e=priorProgressEconomy(e);
 const remove=(r:any,ids:string[])=>Object.fromEntries(Object.entries(r).filter(([key])=>!ids.includes(key))),goods=['vegetables','lunch','boards','fasteners'];
 return {...e,accounts:e.accounts.map((a:any)=>({...a,inventory:remove(a.inventory,goods)})),markets:e.markets.map((m:any)=>({...m,stock:remove(m.stock,goods)})),consumed:remove(e.consumed,goods),batches:remove(e.batches,['pack_lunch','assemble_kit'])};
}
const priorRecipeState=(s:CarState)=>({...preMatchState(s),economy:priorRecipeEconomy(s.economy)});
function priorPlantingEconomy(e:any){
 e=priorRecipeEconomy(e);
 const remove=(r:any,...ids:string[])=>Object.fromEntries(Object.entries(r).filter(([key])=>!ids.includes(key)));
 return {...e,accounts:e.accounts.map((a:any)=>({...a,inventory:remove(a.inventory,'sapling')})),markets:e.markets.map((m:any)=>({...m,stock:remove(m.stock,'sapling')})),consumed:remove(e.consumed,'sapling'),repaired:remove(e.repaired,'orchard_trees'),delivered:remove(e.delivered,'saplings_run')};
}
function expectState(state:CarState,previous:any,scene:Scene){const {population,...actual}=preMatchState(state),{population:old,...rest}=previous;expect({...actual,economy:priorPlantingEconomy(actual.economy)}).toEqual(rest);expectPopulation(state,old,scene);}

it('round-trips reserved work, balances, materials, needs and shared NPC decisions without catch-up',()=>{
 const scene=compileDreamScene(source,{sceneId:'market-save',revisionId:'r1',sourceHash:'current'}),world:World={scene,previousMatchSaveCompatibility:BUSINESS_COMPATIBILITY,previousBusinessSaveCompatibility:SCHOOL_REPAIR_COMPATIBILITY,previousSchoolRepairSaveCompatibility:SOCIAL_COMPATIBILITY,previousSocialSaveCompatibility:SHIFT_COMPATIBILITY,previousShiftSaveCompatibility:HOURS_COMPATIBILITY,previousHoursSaveCompatibility:SEATING_COMPATIBILITY,previousSeatingSaveCompatibility:KITCHEN_COMPATIBILITY,roadMask:buildMaskForScene(scene),driveMask:buildPaperMask(scene.canonical.width,scene.canonical.height),carRadius:11};
 const start={...toggleRide(createCarAtSpawn(scene),world),control:{kind:'foot' as const},x:580,y:750,elevation:0,surface:'paper' as const};
 const state=stepCommerce({...start,timeS:.25},{commerce:{kind:'work',job:'bake'}},.25,scene),restored=decodeSave(encodeSave(state,40,world),world).state;
 expect(restored.economy).toEqual(state.economy);checkEconomyState(restored,scene);
 let a=state,b=restored;for(let i=0;i<8;i++){a=stepCommerce({...a,timeS:a.timeS+.25},{},.25,scene);b=stepCommerce({...b,timeS:b.timeS+.25},{},.25,scene);}expect(b).toEqual(a);expect(b.economy!.batches.bake).toBe(1);
});

